function demoMain(idx,label){
  var suites=[["add(2,3)===5","sub(5,2)===3"],["mul(2,4)===8","div(8,2)===4"],["pow(2,3)===8","mod(7,3)===1"],["max(2,9)===9","min(2,9)===2"]];
  function add(a,b){return a+b;}function sub(a,b){return a-b;}function mul(a,b){return a*b;}
  function div(a,b){return a/b;}function pow(a,b){return Math.pow(a,b);}function mod(a,b){return a%b;}
  function max(a,b){return Math.max(a,b);}function min(a,b){return Math.min(a,b);}
  var s=suites[idx%suites.length];var pass=0;
  s.forEach(function(t){try{if(eval(t))pass++;}catch(e){}});
  return "["+label+"] ran "+s.length+" assertions: "+pass+" passed, "+(s.length-pass)+" failed";
}

